import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"🔬 科学快报 | 2026年8月12日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-12.md","filePath":"science-log/src/reconstructed/2026-08-12.md"}'),n={name:"science-log/src/reconstructed/2026-08-12.md"};function s(i,e,u,l,g,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="🔬-科学快报-2026年8月12日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月12日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月12日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月12日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-06 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202608120000 TO 202608122359]</code>（cs.AI）｜ 重建日：2026-11-06</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🦠-会-尝血糖-的口服益生菌-把降糖药做成活体传感器" tabindex="-1">🦠 会&quot;尝血糖&quot;的口服益生菌：把降糖药做成活体传感器 <a class="header-anchor" href="#🦠-会-尝血糖-的口服益生菌-把降糖药做成活体传感器" aria-label="Permalink to &quot;🦠 会&quot;尝血糖&quot;的口服益生菌：把降糖药做成活体传感器&quot;">​</a></h3><p><strong>Glucose-responsive probiotics for glycaemic modulation in mice and monkeys</strong><em>Nature（2026-08-12）</em></p><p>现有&quot;设计细胞&quot;疗法要么依赖外部信号遥控，要么把合成基因网络装进哺乳动物细胞再移植，安全性与可及性都受限。该研究把葡萄糖感应器做进口服益生菌：用葡萄糖响应转录调控因子 <strong>HexR</strong> 加一个合成启动子搭成基因回路，细菌口服后短暂定植肠道，血糖越过正常阈值才启动治疗性转基因表达，形成&quot;感知—响应&quot;闭环。在多种糖尿病小鼠与非人灵长类模型中，长期口服改善了血糖与血脂谱，并延缓多种糖尿病并发症的发生。它把&quot;按实时血糖给药剂量的活体药&quot;变成了无需移植、可编程的口服平台。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10909-6" target="_blank" rel="noreferrer">10.1038/s41586-026-10909-6</a></p><h3 id="💡-不用光照的超分辨-靠化学反应的光子做-100-nm-成像" tabindex="-1">💡 不用光照的超分辨：靠化学反应的光子做 ~100 nm 成像 <a class="header-anchor" href="#💡-不用光照的超分辨-靠化学反应的光子做-100-nm-成像" aria-label="Permalink to &quot;💡 不用光照的超分辨：靠化学反应的光子做 ~100 nm 成像&quot;">​</a></h3><p><strong>Luminescent-reaction-enabled super-resolution imaging</strong><em>Nature（2026-08-12）</em></p><p>超分辨荧光显微镜一直建立在&quot;外源光激发&quot;之上，而电化学发光（ECL）、化学发光（CL）、生物发光（BL）这类反应激发体系虽无需光照、灵敏度高，却因光子预算太低而被认为分辨率有天花板。作者提出 RIED——把&quot;时空记录策略&quot;与&quot;适配反应驱动光子统计的重建算法&quot;（熵加权相关 + 反卷积）结合的化学型超分辨框架，在 ECL / CL / BL 三种模态下对细胞内细胞器实现约 <strong>100 nm</strong> 分辨率，并用于高灵敏成像。意义在于：超分辨不再必须与强激光和光毒性绑定，活细胞长时程、低损伤成像多了一条化学路线。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10889-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10889-7</a></p><h3 id="🧫-在实体瘤里做全基因组-crispr-筛选-找到-t-细胞-衰竭总闸" tabindex="-1">🧫 在实体瘤里做全基因组 CRISPR 筛选：找到 T 细胞&quot;衰竭总闸&quot; <a class="header-anchor" href="#🧫-在实体瘤里做全基因组-crispr-筛选-找到-t-细胞-衰竭总闸" aria-label="Permalink to &quot;🧫 在实体瘤里做全基因组 CRISPR 筛选：找到 T 细胞&quot;衰竭总闸&quot;&quot;">​</a></h3><p><strong>In vivo genome-wide CRISPR screens of human T cells in solid tumours</strong><em>Nature（2026-08-12）</em></p><p>人 T 细胞的大规模 CRISPR 筛选多在体外做，但实体瘤微环境里的调控因子体外表不出来；体内筛选又长期卡在&quot;瘤内 T 细胞回收率太低&quot;。作者建立了能高效从实体瘤回收人 T 细胞的体内模型，用少量小鼠即可完成全基因组敲除筛选，且瘤内 T 细胞已呈现功能障碍特征。丰度筛选指向 <strong>P2RY8–Gα13</strong> GPCR 轴是瘤内浸润的负调控者；效应功能筛选锁定 <strong>GNAS</strong>（编码 Gαs）为多受体汇聚的衰竭节点——敲除后 T 细胞对多种抑制性配体脱敏，在 CAR 与 TCR 体系中均显著提升疗效，P2RY8/GNAS 双敲效果更好。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10906-9" target="_blank" rel="noreferrer">10.1038/s41586-026-10906-9</a></p><h3 id="🧬-双靶-sirna-同时-刹车-体细胞扩增与亨廷顿蛋白-效果协同" tabindex="-1">🧬 双靶 siRNA：同时&quot;刹车&quot;体细胞扩增与亨廷顿蛋白，效果协同 <a class="header-anchor" href="#🧬-双靶-sirna-同时-刹车-体细胞扩增与亨廷顿蛋白-效果协同" aria-label="Permalink to &quot;🧬 双靶 siRNA：同时&quot;刹车&quot;体细胞扩增与亨廷顿蛋白，效果协同&quot;">​</a></h3><p><strong>Blocking somatic repeat expansion and lowering huntingtin by RNAi synergize to attenuate Huntington&#39;s disease pathogenesis in mice</strong><em>Science Translational Medicine（2026-08-12）</em></p><p>亨廷顿病（HD）的两个核心驱动是体细胞 CAG 重复扩增与毒性 HTT 片段，但此前从未被直接比较或联用。作者用二价 siRNA 在 Q111 模型小鼠（&gt;110 个 CAG，12 月龄已出现明显扩增、包涵体与转录失调）中分别沉默 <strong>MSH3</strong>（错配修复关键因子、扩增的驱动者）、HTT 或两者：长期沉默 MSH3 阻断体细胞扩增、减少包涵体并让基因表达谱回归正常；单降 HTT 效果有限；而 MSH3/HTT 联合呈现<strong>协同</strong>获益。这解释了为何单纯降 HTT 的临床试验屡屡令人失望——上游的&quot;扩增引擎&quot;没关掉，毒性片段仍在源源不断产生。</p><p>📎 DOI: <a href="https://doi.org/10.1126/scitranslmed.aea3104" target="_blank" rel="noreferrer">10.1126/scitranslmed.aea3104</a></p><h3 id="👶-婴儿为何看几眼就会归类-日常视觉经验的-块状-统计结构" tabindex="-1">👶 婴儿为何看几眼就会归类：日常视觉经验的&quot;块状&quot;统计结构 <a class="header-anchor" href="#👶-婴儿为何看几眼就会归类-日常视觉经验的-块状-统计结构" aria-label="Permalink to &quot;👶 婴儿为何看几眼就会归类：日常视觉经验的&quot;块状&quot;统计结构&quot;">​</a></h3><p><strong>A solution to generalized learning from small training sets found in infants&#39; repeated visual experiences of individual objects</strong><em>PNAS（2026-08-12）</em></p><p>一岁婴儿能从极少数样例迅速形成并泛化类别，这与机器学习&quot;小样本难泛化&quot;的困境形成对照。作者用 14 名婴儿、87 次进餐时段的头戴相机影像，量化 8 个物体类别的日常视觉统计：个体经验中各类实例的出现频次高度偏斜——少数几个物体反复出现，其余只是一瞥；用图论指标衡量则呈现&quot;块状&quot;（lumpy）结构，即高相似度与高变异并存，并组织成多个彼此连通的相似图像簇。计算实验进一步显示，由&quot;高相似簇互联&quot;构成的训练集，能让模型在有限训练后泛化到新实例。这提示泛化能力可能不取决于样本数量，而取决于经验的<strong>拓扑结构</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2536143123" target="_blank" rel="noreferrer">10.1073/pnas.2536143123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🚦-steerbench-work-智能体-按下回车之前-该不该停" tabindex="-1">🚦 SteerBench-Work：智能体&quot;按下回车之前&quot;该不该停 <a class="header-anchor" href="#🚦-steerbench-work-智能体-按下回车之前-该不该停" aria-label="Permalink to &quot;🚦 SteerBench-Work：智能体&quot;按下回车之前&quot;该不该停&quot;">​</a></h3><p><strong>SteerBench-Work: A Benchmark for Agent Steering at Action Boundaries</strong><em>arXiv:2608.12654（2026-08-12）</em></p><p>长时程智能体通过工具行动，单步就可能发出邮件、合并 PR 或划转付款。真正的控制点不是&quot;想什么&quot;，而是行动边界前那个&quot;执行 / 挂起待审&quot;的决策。作者发布 SteerBench-Work：以真实公开事故为锚、覆盖研发运维/客服/金融/法务/医疗/HR/安全七类职场场景的双向基准，v2026-05 含 <strong>106</strong> 个场景，配&quot;证据反转镜像&quot;与校准控制项，proceed 与 hold 标签近乎各半，使两类错误（误放行 / 误拦截）获得几乎相同的考察机会。模型只看到拟执行动作与可用证据，输出门控决定并接受双向评分。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.12654" target="_blank" rel="noreferrer">2608.12654</a></p><h3 id="⚖️-摇摆的裁判-llm-评判者的-认知稳定性-压力测试" tabindex="-1">⚖️ 摇摆的裁判：LLM 评判者的&quot;认知稳定性&quot;压力测试 <a class="header-anchor" href="#⚖️-摇摆的裁判-llm-评判者的-认知稳定性-压力测试" aria-label="Permalink to &quot;⚖️ 摇摆的裁判：LLM 评判者的&quot;认知稳定性&quot;压力测试&quot;">​</a></h3><p><strong>Jagged Judges: Epistemic Stability Under Perturbation, Pressure, and Persistence</strong><em>arXiv:2608.12645（2026-08-12）</em></p><p>LLM 裁判已是评测、在线打分与奖励建模的基础设施，但通常只用黄金数据上的准确率验证——准确率说明不了它在重复提问、被质疑、被持续施压时是否还站得住。作者提出 <strong>Wiggle Framework</strong>，把稳健性拆成三维：机械一致性（重述/改写下是否稳定）、单轮信念（一次挑战下是否守住）、多轮持久性（持续或自适应施压下是否守住），并在安全、毒性、AI 写作检测、政治回应评估等 14 类任务上测了 9 个前沿模型。这把&quot;裁判可靠性&quot;从静态准确率问题，改写成动态对抗下的稳定性问题。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.12645" target="_blank" rel="noreferrer">2608.12645</a></p><h3 id="🧾-死文本还是约束条款-多轮对话里的-撤销失效" tabindex="-1">🧾 死文本还是约束条款：多轮对话里的&quot;撤销失效&quot; <a class="header-anchor" href="#🧾-死文本还是约束条款-多轮对话里的-撤销失效" aria-label="Permalink to &quot;🧾 死文本还是约束条款：多轮对话里的&quot;撤销失效&quot;&quot;">​</a></h3><p><strong>Dead text or binding clause? Measuring and restoring constraint influence in black-box LLM dialogues</strong><em>arXiv:2608.12599（2026-08-12）</em></p><p>多轮对话中用户撤销约束与施加约束一样容易，但撤销并不真的生效：模型继续执行已被撤回的要求，甚至在声称已移除的注释下照做——作者称之为<strong>行为复发（behavioral relapse）/ 撤销惯性</strong>。工具通过纯 API 闭合三个缺口：契约账本把每条约束与可执行检查器配对、把撤销记为&quot;墓碑&quot;并预编译净约束状态；顺序消融探针测出逐条遵守度与增量行为效应；修复阶梯在匹配的 token 预算下执行补救。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.12599" target="_blank" rel="noreferrer">2608.12599</a></p><h3 id="🎥-egocite-把第一人称生活流变成可检索的记忆" tabindex="-1">🎥 EgoCITE：把第一人称生活流变成可检索的记忆 <a class="header-anchor" href="#🎥-egocite-把第一人称生活流变成可检索的记忆" aria-label="Permalink to &quot;🎥 EgoCITE：把第一人称生活流变成可检索的记忆&quot;">​</a></h3><p><strong>EgoCITE: Context-Augmented Indexing and Time-Aware Retrieval for Long-Horizon Egocentric Memory</strong><em>arXiv:2608.12627（2026-08-12）</em></p><p>长时程自我中心记忆要把连续的第一人称视频与音频变成可搜索的过往经历，作者指出现有系统的两个瓶颈：索引建立在&quot;缺上下文&quot;的碎片化描述上，检索又忽略问题的<strong>时间意图</strong>。EgoCITE 用三个部件应对：EgoScheme 借局部多模态上下文把碎片字幕与语音转写补成自足的原子记忆索引；EgoIndex 把动作、活动、话语、对话四种表征组织成多视角可检索记忆；再以时间感知的检索对齐问题的时间意图。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.12627" target="_blank" rel="noreferrer">2608.12627</a></p><h3 id="📖-模型写的小说-形式变异被-压扁-了" tabindex="-1">📖 模型写的小说，形式变异被&quot;压扁&quot;了 <a class="header-anchor" href="#📖-模型写的小说-形式变异被-压扁-了" aria-label="Permalink to &quot;📖 模型写的小说，形式变异被&quot;压扁&quot;了&quot;">​</a></h3><p><strong>Novels generated by language models show compressed formal variation</strong><em>arXiv:2608.12630（2026-08-12）</em></p><p>已有研究多问&quot;某段文字能否被判为 AI 生成&quot;，本文改问：反复生成能否覆盖人类语料那种多样性范围。作者对比六组语料——GPT-5.5 Thinking 与 Qwen3-14B 各按 19 世纪英国现实主义风格生成 20 部小说、两模型各以当代&quot;零风格&quot;生成 20 部，以及 205 部 19 世纪人类小说、65 部当代人类小说，测量形式变异。结论是模型产出的形式变异被压缩：单篇可辨不出，但语料层面的多样性光谱明显窄于人类。对创作的启示是，&quot;像人写&quot;与&quot;像人类文学生态&quot;是两件事。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.12630" target="_blank" rel="noreferrer">2608.12630</a></p><blockquote><p>📅 日期：2026-08-12 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const p=t(n,[["render",s]]);export{h as __pageData,p as default};
